// Fixed-window request limiter, one counter per tenant.
export interface LimiterConfig {
  readonly limit: number;
  readonly windowMs: number;
}

export interface Decision {
  readonly allowed: boolean;
  readonly remaining: number;
}

interface WindowState {
  start: number;
  used: number;
}

export function createLimiter(config: LimiterConfig) {
  const windows = new Map<string, WindowState>();
  return {
    check(tenant: string, now: number): Decision {
      let state = windows.get(tenant);
      if (state === undefined || now - state.start >= config.windowMs) {
        state = { start: now, used: 0 };
        windows.set(tenant, state);
      }
      if (state.used >= config.limit) return { allowed: false, remaining: 0 };
      state.used += 1;
      return { allowed: true, remaining: config.limit - state.used };
    },
  };
}

