// Resolves a user's preferences: workspace defaults overlaid with the user's own overrides.
export type Preferences = Readonly<Record<string, string>>;

export interface PreferenceSource {
  fetchDefaults(workspace: string): Promise<Preferences>;
  fetchOverrides(workspace: string, user: string): Promise<Preferences>;
}

export interface CacheOptions {
  readonly ttlMs: number;
  readonly now: () => number;
}

function isNotFound(error: unknown): boolean {
  return typeof error === "object" && error !== null && (error as { code?: unknown }).code === "not_found";
}

async function loadOverrides(source: PreferenceSource, workspace: string, user: string): Promise<Preferences> {
  try {
    return await source.fetchOverrides(workspace, user);
  } catch (error) {
    if (isNotFound(error)) return {};
    throw error;
  }
}

export async function resolvePreferences(source: PreferenceSource, workspace: string, user: string): Promise<Preferences> {
  const defaults = await source.fetchDefaults(workspace);
  const overrides = await loadOverrides(source, workspace, user);
  return { ...defaults, ...overrides };
}

interface Entry {
  readonly startedAt: number;
  readonly value: Promise<Preferences>;
}

export function createPreferenceCache(source: PreferenceSource, options: CacheOptions) {
  const entries = new Map<string, Entry>();
  return {
    get(workspace: string, user: string): Promise<Preferences> {
      const key = JSON.stringify([workspace, user]);
      const now = options.now();
      const current = entries.get(key);
      if (current !== undefined && now < current.startedAt + options.ttlMs) return current.value;
      const entry: Entry = { startedAt: now, value: resolvePreferences(source, workspace, user) };
      entries.set(key, entry);
      entry.value.catch(() => {
        if (entries.get(key) === entry) entries.delete(key);
      });
      return entry.value;
    },
  };
}

